let data = msg.payload
if (typeof data === 'string') {
  try { data = JSON.parse(data) } catch(e) {}
}
if (!data || typeof data !== 'object') return null

const humOn  = parseFloat(env.get('LAUNDRY_HUMIDITY_THRESHOLD') || '70')
const humOff = parseFloat(env.get('LAUNDRY_HUMIDITY_OFF')       || '60')
const tmpOn  = parseFloat(env.get('LAUNDRY_TEMP_THRESHOLD')     || '28')
const tmpOff = parseFloat(env.get('LAUNDRY_TEMP_OFF')           || '25')

const states = flow.get('states') || {}
let changed = false

if (data.humidity !== undefined) {
  if (!states.humidity && data.humidity > humOn)  { states.humidity = true;  changed = true }
  if ( states.humidity && data.humidity < humOff) { states.humidity = false; changed = true }
}
if (data.temperature !== undefined) {
  if (!states.temperature && data.temperature > tmpOn)  { states.temperature = true;  changed = true }
  if ( states.temperature && data.temperature < tmpOff) { states.temperature = false; changed = true }
}

if (changed) {
  flow.set('states', states)
  return { payload: 'evaluate' }
}
return null

const states = flow.get('states') || {}

if (states.manual) {
  // Bereits manuell AN → ausschalten
  if (states.manual_timer) {
    clearTimeout(states.manual_timer)
  }
  states.manual = false
  states.manual_until = null
  states.manual_timer = null
} else {
  // Manuell einschalten mit Timer
  const duration = parseInt(env.get('LAUNDRY_MANUAL_TIMER_SECONDS') || '7200') * 1000
  states.manual_until = Date.now() + duration
  states.manual = true
  states.manual_timer = setTimeout(() => {
    const s = flow.get('states') || {}
    s.manual = false
    s.manual_until = null
    s.manual_timer = null
    flow.set('states', s)
    node.send({ payload: 'manual_timer_expired' })
  }, duration)
}

flow.set('states', states)
return { payload: 'evaluate' }

const states = flow.get('states') || {}
const now = Date.now()

const manualActive = states.manual && states.manual_until && states.manual_until > now
const autoActive   = states.humidity || states.temperature || states.tumbler || states.washing
const isOn         = manualActive || autoActive

const mode = isOn ? (manualActive ? 'manual' : 'auto') : 'off'
const trigger = manualActive ? 'manual'
  : states.humidity    ? 'humidity'
  : states.temperature ? 'temperature'
  : states.tumbler     ? 'tumbler'
  : states.washing     ? 'washing'
  : null
const remainingSeconds = manualActive
  ? Math.round((states.manual_until - now) / 1000)
  : null

const appliancePayload = JSON.stringify({
  state:            isOn ? 'on' : 'off',
  mode,
  trigger,
  remaining_seconds: remainingSeconds
})

const shellyTopic = env.get('LAUNDRY_FAN_SHELLY_TOPIC') || 'shellies/fan-waschkueche/relay/0/command'
const panels      = (env.get('LAUNDRY_PANELS') || 'kitchen').split(',').map(p => p.trim())
const applianceId = 'ventilator_waschkueche'

// Output 1 – Shelly relay
node.send([{ topic: shellyTopic, payload: isOn ? 'on' : 'off', qos: 1, retain: true }, null, null])

// Output 2 – Appliance state (pro Panel)
for (const panel of panels) {
  node.send([null, {
    topic:   `dashboard/panels/${panel}/appliances/${applianceId}/state`,
    payload: appliancePayload,
    qos:     1,
    retain:  true
  }, null])
}

// Output 3 – Light state (für light_states im Store, pro Panel)
for (const panel of panels) {
  node.send([null, null, {
    topic:   `dashboard/panels/${panel}/lights/${applianceId}/state`,
    payload: isOn ? 'on' : 'off',
    qos:     1,
    retain:  true
  }])
}

return null
